use std::collections::HashMap;
use std::sync::Arc;

/// Cloud Infrastructure SDK - Request Router with RBAC
/// Handles service mesh routing with role-based access control

#[derive(Clone, Debug, PartialEq)]
pub enum Role {
    Admin,
    Developer,
    ReadOnly,
    ServiceAccount,
}

#[derive(Clone, Debug)]
pub struct Principal {
    pub id: String,
    pub role: Role,
    pub tenant_id: String,
}

#[derive(Clone, Debug)]
pub struct RouteConfig {
    pub allowed_roles: Vec<Role>,
    pub base_url: String,
    pub require_same_tenant: bool,
}

#[derive(Clone, Debug)]
pub struct RedirectResponse {
    pub status: u16,
    pub location: String,
}

pub struct ServiceRouter {
    routes: HashMap<String, RouteConfig>,
    trusted_domains: Vec<String>,
}

impl ServiceRouter {
    pub fn new() -> Self {
        let mut routes = HashMap::new();
        routes.insert("dashboard".to_string(), RouteConfig {
            allowed_roles: vec![Role::Admin, Role::Developer, Role::ReadOnly],
            base_url: "https://dashboard.internal.cloud".to_string(),
            require_same_tenant: true,
        });
        routes.insert("api".to_string(), RouteConfig {
            allowed_roles: vec![Role::Admin, Role::Developer, Role::ServiceAccount],
            base_url: "https://api.internal.cloud".to_string(),
            require_same_tenant: true,
        });
        routes.insert("docs".to_string(), RouteConfig {
            allowed_roles: vec![Role::Admin, Role::Developer, Role::ReadOnly, Role::ServiceAccount],
            base_url: "https://docs.internal.cloud".to_string(),
            require_same_tenant: false,
        });

        ServiceRouter {
            routes,
            trusted_domains: vec![
                "internal.cloud".to_string(),
                "cdn.internal.cloud".to_string(),
                "auth.internal.cloud".to_string(),
            ],
        }
    }

    /// Validates that the principal has the required role for the route
    fn check_rbac(&self, principal: &Principal, config: &RouteConfig) -> bool {
        config.allowed_roles.contains(&principal.role)
    }

    /// Validates tenant isolation
    fn check_tenant(&self, principal: &Principal, target_tenant: &str, config: &RouteConfig) -> bool {
        if !config.require_same_tenant {
            return true;
        }
        principal.tenant_id == target_tenant || principal.role == Role::Admin
    }

    /// Normalizes the URL path component, resolving relative segments
    fn normalize_path(&self, path: &str) -> String {
        let segments: Vec<&str> = path.split('/').collect();
        let mut normalized: Vec<&str> = Vec::new();

        for segment in segments {
            match segment {
                "" | "." => continue,
                ".." => { normalized.pop(); },
                s => normalized.push(s),
            }
        }

        format!("/{}", normalized.join("/"))
    }

    /// Validates that a URL belongs to a trusted domain
    fn is_trusted_url(&self, url: &str) -> bool {
        // Extract the host from the URL
        if let Some(host) = self.extract_host(url) {
            return self.trusted_domains.iter().any(|d| host.ends_with(d));
        }
        false
    }

    /// Extracts host from a URL string
    fn extract_host(&self, url: &str) -> Option<String> {
        // Handle protocol-relative URLs
        let without_scheme = if url.starts_with("https://") {
            &url[8..]
        } else if url.starts_with("http://") {
            &url[7..]
        } else {
            return None;
        };

        // Extract host portion (before first / or end)
        let host = without_scheme.split('/').next()?;
        // Remove port if present
        let host = host.split(':').next()?;
        Some(host.to_lowercase())
    }

    /// Constructs the final redirect URL from route config and user-supplied path
    fn build_redirect_url(&self, config: &RouteConfig, path: &str, callback_url: Option<&str>) -> String {
        let normalized = self.normalize_path(path);

        // If a callback URL is provided and passes trust validation, use it
        if let Some(callback) = callback_url {
            if self.is_trusted_url(callback) {
                return format!("{}{}", callback, normalized);
            }
        }

        format!("{}{}", config.base_url, normalized)
    }

    /// Main routing function - processes a redirect request with full RBAC
    pub fn route_request(
        &self,
        principal: &Principal,
        service: &str,
        target_tenant: &str,
        path: &str,
        callback_url: Option<&str>,
    ) -> Result<RedirectResponse, String> {
        // Step 1: Look up route configuration
        let config = self.routes.get(service)
            .ok_or_else(|| format!("Unknown service: {}", service))?;

        // Step 2: RBAC check
        if !self.check_rbac(principal, config) {
            return Err(format!("Access denied: role {:?} not permitted for service {}", 
                principal.role, service));
        }

        // Step 3: Tenant isolation check
        if !self.check_tenant(principal, target_tenant, config) {
            return Err(format!("Tenant isolation violation: {} cannot access tenant {}",
                principal.tenant_id, target_tenant));
        }

        // Step 4: Build and validate redirect
        let location = self.build_redirect_url(config, path, callback_url);

        Ok(RedirectResponse {
            status: 302,
            location,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_routing() {
        let router = ServiceRouter::new();
        let principal = Principal {
            id: "user1".to_string(),
            role: Role::Developer,
            tenant_id: "tenant-a".to_string(),
        };

        let result = router.route_request(&principal, "dashboard", "tenant-a", "/home", None);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().location, "https://dashboard.internal.cloud/home");
    }

    #[test]
    fn test_rbac_denied() {
        let router = ServiceRouter::new();
        let principal = Principal {
            id: "user2".to_string(),
            role: Role::ReadOnly,
            tenant_id: "tenant-a".to_string(),
        };

        let result = router.route_request(&principal, "api", "tenant-a", "/v1/resources", None);
        assert!(result.is_err());
    }
}
